import { PassThrough } from 'node:stream'
import { describe, expect, it } from 'vitest'
import {
  createMessageConnection,
  StreamMessageReader,
  StreamMessageWriter,
  type CancellationToken,
  type MessageConnection
} from 'vscode-jsonrpc/node'
import type { WslConnectionState } from '../shared/wsl'
import { WslConnections, type WslHelperProcess } from './wsl-connection'

interface ExecParams {
  file: string
  args: string[]
  cwd: string
  env?: Record<string, string>
  stdin?: string
  stream?: string
}

type ExecHandler = (
  p: ExecParams,
  token: CancellationToken,
  notify: (fd: 'stdout' | 'stderr', text: string) => void
) => unknown

/** 内存里的假小助手：另一端用同一个 JSON-RPC 库应答（协议同 build/wsl/server.go）。 */
function fakeHelper(
  options: {
    exec?: ExecHandler
    initialize?: boolean
    stderr?: string
    onServer?: (server: MessageConnection) => void
  } = {}
): WslHelperProcess & { crash(): void } {
  const stdin = new PassThrough()
  const stdout = new PassThrough()
  const stderr = new PassThrough()
  let finish: (reason: string | null) => void = () => {}
  const exited = new Promise<string | null>((resolve) => (finish = resolve))
  const server = createMessageConnection(
    new StreamMessageReader(stdin),
    new StreamMessageWriter(stdout)
  )
  // initialize: false 即一直不应答（模拟卡住或没起来）
  server.onRequest('initialize', () =>
    options.initialize === false
      ? new Promise(() => {})
      : {
          executable: '/mnt/c/DevCube/resources/wsl/devcube-wsl',
          shell: '/bin/bash',
          runDir: '/tmp/devcube-wsl-runs-1'
        }
  )
  server.onRequest('exec', (p: ExecParams, token) =>
    (options.exec ?? (() => ({ code: 0 })))(p, token, (fd, text) => {
      void server.sendNotification('exec/data', {
        stream: p.stream,
        fd,
        data: Buffer.from(text).toString('base64')
      })
    })
  )
  options.onServer?.(server)
  server.listen()
  const end = (): void => {
    server.dispose()
    finish(null)
  }
  if (options.stderr !== undefined) {
    stderr.write(options.stderr)
    setTimeout(end, 0)
  }
  return { stdin, stdout, stderr, exited, kill: end, crash: end }
}

interface Setup {
  connections: WslConnections
  spawned: Array<ReturnType<typeof fakeHelper>>
  states: WslConnectionState[]
}

function setup(
  options: {
    preflight?: string | null
    helpers?: Array<ReturnType<typeof fakeHelper>>
    time

// WSL 连接前的检查（docs/prd/wsl-project.md「连不上」）：连接失败时给出能看懂、能照着修的原因，
// 而不是 wsl.exe 的原始报错。只在连接时跑，结果不缓存（用户可能刚装好或刚转换完）。
import { execFile } from 'node:child_process'
import { promisify } from 'node:util'

const execFileAsync = promisify(execFile)

/** 注册表里登记的一个发行版。 */
export interface WslDistroInfo {
  name: string
  /** WSL 1 / WSL 2：看 Flags 的 0x8 位（VM 模式），不看 Version（那是文件系统布局的版本） */
  wsl2: boolean
}

const LXSS_KEY = 'HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Lxss'
/** LXSS_DISTRO_FLAGS_VM_MODE（microsoft/WSL 源码 DistributionRegistration.h） */
const VM_MODE_FLAG = 0x8

/** 解析 `reg query <Lxss> /s` 的输出：每个发行版子键取 DistributionName 与 Flags。 */
export function parseLxssRegistry(output: string): WslDistroInfo[] {
  const distros: WslDistroInfo[] = []
  let name: string | null = null
  let flags = 0
  const flush = (): void => {
    if (name !== null) distros.push({ name, wsl2: (flags & VM_MODE_FLAG) !== 0 })
    name = null
    flags = 0
  }
  for (const line of output.split(/\r?\n/)) {
    if (/^HKEY_/i.test(line)) {
      flush()
      continue
    }
    const value = /^\s+(\S+)\s+(REG_\w+)\s+(.*)$/.exec(line)
    if (!value) continue
    if (value[1] === 'DistributionName') name = value[3].trim()
    else if (value[1] === 'Flags') flags = Number.parseInt(value[3].trim(), 16) || 0
  }
  flush()
  return distros
}

/** 连接前检查需要的事实（注入以便测试）。 */
export interface WslPreflightFacts {
  /** `wsl.exe --version` 能跑通（Microsoft Store 版 WSL 才有这个参数） */
  storeWsl: boolean
  distros: readonly WslDistroInfo[]
  /** 安装包里带了小助手 */
  helperPresent: boolean
}

/** 连不上的原因；能连返回 null。发行版名不分大小写（WSL 自己就不分）。 */
export function wslPreflightReason(distro: string, facts: WslPreflightFacts): string | null {
  if (!facts.storeWsl && facts.distros.length === 0) return '未安装 WSL'
  if (!facts.storeWsl) return 'WSL 版本过旧，请运行 wsl --update 更新'
  const info = facts.distros.find((d) => d.name.toLowerCase() === distro.toLowerCase())
  if (!info) return `未找到发行版 ${distro}`
  if (!info.wsl2)
    return `${distro} 是 WSL 1 发行版，请先运行 wsl --set-version ${distro} 2 转换为 WSL 2`
  if (!facts.helperPresent) return 'DevCube 缺少 WSL 组件，请重新安装'
  return null
}

/** 读注册表里登记的发行版；没有这个键（从没装过发行版）即为空。 */
export async function readWslDistros(): Promise<WslDistroInfo[]> {
  try {
    const { stdout } = await execFileAsync('reg', ['query', LXSS_KEY, '/s'], { windowsHide: true })
    return parseLxssRegistry(stdout)
  } catch {
    return []
  }
}

/** Microsoft Store 版 WSL 才认 `--version`；系统自带的旧版与未安装时的占位 wsl.exe 都会报错退出。 */
export async function isStoreWsl(wslExe: string): Promise<boolean> {
  try {
    await execFileAsync(wslExe, ['--version'], { windowsHide: true, timeout: 15_000 })
    return true
  } catch {
    return false
  }
}
/**
 * 准备 WSL 小助手（ADR-0055）：交叉编译 build/wsl 的 Go 程序为 Linux x86_64 静态程序，
 * 并取与 @vscode/ripgrep 同版本的 Linux x64 版 rg（静态链接），一起放到 build/wsl/out。
 * 打包 Windows 前运行（`pnpm build:win` / release 工作流）；产物只由 electron-builder 的 win.extraResources 带进 resources/wsl，
 * Mac 与 Linux 安装包不带。只出 x86_64（与 Windows 发布目标 x64 对应）。需要 Go 工具链。
 */
import { execFileSync } from 'node:child_process'
import {
  copyFileSync,
  chmodSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync
} from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const source = resolve(root, 'build/wsl')
const out = resolve(source, 'out')
mkdirSync(out, { recursive: true })

execFileSync('go', ['build', '-trimpath', '-ldflags=-s -w', '-o', join(out, 'devcube-wsl'), '.'], {
  cwd: source,
  stdio: 'inherit',
  env: { ...process.env, GOOS: 'linux', GOARCH: 'amd64', CGO_ENABLED: '0' }
})

// rg 的 Linux 版是 @vscode/ripgrep 按平台拆出的独立包，本机只装了自身平台那一个；按同一版本从 npm 取包解出 bin/rg
const { version } = JSON.parse(
  readFileSync(resolve(root, 'node_modules/@vscode/ripgrep/package.json'), 'utf8')
) as { version: string }
const work = mkdtempSync(join(tmpdir(), 'devcube-wsl-rg-'))
try {
  execFileSync('npm', ['pack', `@vscode/ripgrep-linux-x64@${version}`, '--silent'], {
    cwd: work,
    stdio: ['ignore', 'ignore', 'inherit'],
    shell: process.platform === 'win32'
  })
  const tarball = readdirSync(work).find((name) => name.endsWith('.tgz'))
  if (!tarball) throw new Error('未取到 @vscode/ripgrep-linux-x64')
  execFileSync('tar', ['-xzf', tarball], { cwd: work, stdio: 'inherit' })
  copyFileSync(join(work, 'package', 'bin', 'rg'), join(out, 'rg'))
  chmodSync(join(out, 'rg'), 0o755)
} finally {
  rmSync(work, { recursive: true, force: true })
}
console.log(`[wsl-helper] built ${out}（rg ${version}）`)
