import { mkdirSync } from 'node:fs'
import { join } from 'node:path'
import { resolveReleaseEdition } from '../shared/release-edition'

const DEVELOPMENT_USER_DATA_DIRECTORY = 'DevCube Dev'

type UserDataApp = {
  isPackaged: boolean
  getVersion(): string
  getPath(name: 'appData'): string
  setPath(name: 'userData' | 'sessionData', path: string): void
}

/**
 * 为 Stable、Beta 与 Dev 显式固定各自的数据目录。
 * 必须在 app.ready、Store 初始化和 Chromium Session 创建之前调用。
 */
export function configureUserData(app: UserDataApp): void {
  const directory = app.isPackaged
    ? resolveReleaseEdition(app.getVersion()).userDataDirectory
    : DEVELOPMENT_USER_DATA_DIRECTORY
  const dataPath = join(app.getPath('appData'), directory)

  // Electron 官方要求 setPath 的目标目录已存在且为绝对路径。
  mkdirSync(dataPath, { recursive: true })
  app.setPath('userData', dataPath)
  app.setPath('sessionData', dataPath)
}
// 用户的文件用不带 asar 改装的原版 fs：Electron 改装过的 fs 会把 .asar 文件当成文件夹往里读（ADR-0051）
import { readFileSync, rmSync, statSync } from 'original-fs'
import { tmpdir } from 'node:os'
import { basename, dirname, isAbsolute, resolve } from 'node:path'

/**
 * External Open（外部唤起）：deep link / 启动参数的解析与「就绪前排队」。术语见 CONTEXT.md。
 * 打开：目录 → 项目语义（登记或聚焦）；文件 → Preview Window（docs/prd/file-preview-window.md）。
 * 压缩：一组路径 → 压缩窗口（docs/prd/compress.md）。
 */

export type ExternalOpenKind = 'dir' | 'file'

export type ExternalOpenTarget =
  { kind: ExternalOpenKind; path: string } | { kind: 'compress'; paths: string[] }

export type ExternalOpenDeps = {
  /** 判定路径是目录 / 文件 / 都不是（解析层的 IO，注入以便测试） */
  classify: (path: string) => ExternalOpenKind | null
  /** 读出并删掉压缩清单文件（一行一个路径）；不是我们写的清单文件则返回空 */
  takeCompressList: (file: string) => string[]
}

/** 压缩请求的启动参数：Windows 右键扩展以 `--compress <路径…>` 启动（ADR-0049）。 */
export const COMPRESS_ARG = '--compress'
/** 路径太多、命令行装不下时，右键扩展改把清单写进临时目录，以 `--compress-list=<文件>` 传入。 */
export const COMPRESS_LIST_ARG = '--compress-list='
const COMPRESS_LIST_FILE = /^devcube-compress-[\w-]+\.txt$/

/** 只认临时目录里按约定命名的清单文件：解析参数会删掉它，不能让任意参数指向别的文件。 */
export function isCompressListFile(file: string, tempDir: string): boolean {
  const sameDir =
    process.platform === 'win32'
      ? dirname(file).toLowerCase() === resolve(tempDir).toLowerCase()
      : dirname(file) === resolve(tempDir)
  return isAbsolute(file) && sameDir && COMPRESS_LIST_FILE.test(basename(file))
}

const defaultDeps: ExternalOpenDeps = {
  classify: (path) => {
    try {
      const st = statSync(path)
      if (st.isDirectory()) return 'dir'
      if (st.isFile()) return 'file'
      return null
    } catch {
      return null
    }
  },
  takeCompressList: (file) => {
    if (!isCompressListFile(file, tmpdir())) return []
    try {
      return readFileSync(file, 'utf8')
        .split(/\r?\n/)
        .filter((line) => line !== '')
    } catch {
      return []
    } finally {
      rmSync(file, { force: true })
    }
  }
}

export type DeepLink = { action: 'open'; path: string } | { action: 'compress'; paths: string[] }

/**
 * deep link 认两种：`<scheme>://open?path=<绝对路径>` 与 `<scheme>://compress?path=<绝对路径>&path=…`；
 * 其余形态一律 null。
 */
export function parseDeepLink(url: string, scheme: string): DeepLink | null {
  let parsed: URL
  try {
    parsed = new URL(url)
  } catch {
    return null
  }
  if (parsed.protocol !== `${scheme}:`) return null
  // `scheme://open` 的 open 落在 host；`scheme:open` 等无 `//` 形态落在 pathname。
  const action = parsed.host !== '' ? parsed.host : parsed.pathname.replace(/^\/+/, '')
  const usable = (path: string): boolean => path !== '' && isAbsolute(path)
  if (action === 'open') {
    const path = parsed.searchParams.get('path')
    return path !== null && usable(path) ? { action: 'open', path } : null
  }
  if (action === 'compress') {
    const paths = parsed.searchParams.getAll('path').filter(usable)
    return paths.length > 0 ? { action: 'compress', paths } : null
  }
  return null
}

/** deep link → 目标：路径须存在；压缩只留存在的路径，全都不在则 null。 */
export function targetFromDeepLink(
  link: DeepLink,
  deps: ExternalOpenDeps = defaultDeps
): ExternalOpenTarget | null {
  if (link.action === 'open') {
    const kind = deps.classify(link.path)
    return kind === null ? null : { kind, path: link.path }
  }
  const paths = [...new Set(link.paths)].filter((p) => deps.classify(p) !== null)
  return paths.length > 0 ? { kind: 'compress', paths } : null
}

/**
  // 已开启的系统入口与当前构建对齐（Windows 压缩右键扩展：DLL 换了版本或唤起命令变了就重新登记）；
  // 失败只记日志，不影响启动。
  syncSystemIntegration().catch((err) => {
    console.warn('[system-integration] sync failed', err)
  })

  // 运行中的 External Open（第二实例 / open-file / open-url）
  setExternalOpenHandler(handleExternalOpen)

  app.on('activate', function () {
    // On macOS re-create a window when the dock icon is clicked and none are open.
    if (isAppQuitting()) return
    if (BrowserWindow.getAllWindows().length === 0) openMainWindow()
  })
})

// Cmd+Q / app.quit() 会走 before-quit，但不会发 window-all-closed（Electron 官方说明）。
// 退出清理必须在这里完成：先 await 关掉原生文件监听，再 app.exit（官方对原生 addon 的要求是
// 退出前显式 destroy；用 app.exit 避免再入 before-quit）。清理期间禁止 sync* 重建监听。
type QuitPhase = 'running' | 'cleaning' | 'exiting'
let quitPhase: QuitPhase = 'running'

async function runQuitCleanup(): Promise<void> {
  markAppQuitting()
  // 退出用 app.exit 直接销毁窗口、不走关窗事件：还开着的窗口在这里记下几何
  const main = liveMainWindow()
  if (main) rememberWindowPlacement(main, 'main')
  rememberPreviewWindowPlacement()
  disposeTray()
  killAllSessions()
  closeAllWsl()
  disposeAllServerStatus()
  disposeAllServerFiles()
  clearAllServerFilesCache()
  // 数据库连接与 SQLite 查询线程也在这里关掉（含数总行数、导出、连上后读主体结构等临时连接）；还在执行的语句先叫停，
  // 最多等 2 秒。表结构缓存把待写的写完。进行中的压缩结束线程、删掉写了一半的临时文件
  await Promise.all([
    closeAllProjectWatchers(),
    closeAllPreviewWatchers(),
    disposeAllDataSourceSessions(),
    flushSchemaCaches(),
    disposeAllCompressJobs()
  ])
  // 给原生 watcher stop 一点时间收尾，再拆 Node Environment。
  await new Promise<void>((resolve) => setTimeout(resolve, 50))
}

app.on('before-quit', (event) => {
  if (quitPhase === 'exiting') return
  event.preventDefault()
  if (quitPhase === 'cleaning') return

  void (async () => {
    if (!isQuitAllowed()) {
      const ok = await confirmQuitIfNeeded(BrowserWindow.getFocusedWindow())
      if (!ok) return
      markQuitAllowed()
    }

    quitPhase = 'cleaning'
    try {
      await runQuitCleanup()
    } catch {
      // ignore
    }

    // 有待装更新：标 exiting 后跳出 before-quit 再 install（Squirrel.Mac 忌在带
    // preventDefault 的 before-quit 同步栈里 quitAndInstall，见 ADR-0016）。
    if (canInstallUpdateOnQuit()) {
      quitPhase = 'exiting'
      setImmediate(() => installDownloadedUpdate())
      return
    }

    quitPhase = 'exiting'
    app.exit(0)
  })()
})

// Quit when all windows are closed, except on macOS / Windows（托盘驻留）。
app.on('window-all-closed', () => {
  // macOS / Windows 关窗不退出：保留运行中的会话进程，重开后仍能恢复运行状态。
  // 真正退出清理在 before-quit；此处仅在「只关窗、不退出」时停掉无 UI 的文件监听。
  // Windows 正常点关闭是 hide 不会进这里；窗口被销毁时仍不 quit。
  if (process.platform === 'darwin' || process.platform === 'win32') {
    void closeAllProjectWatchers()
    return
  }
  app.quit()
})
